begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email) values
 ('00000000-0000-4000-8000-000000000038','authenticated','authenticated','mail038@example.invalid'),
 ('00000000-0000-4000-8000-000000000138','authenticated','authenticated','mail038-other@example.invalid');
create temporary table source38 as select * from public.save_knowledge_source('00000000-0000-4000-8000-000000000038','Tarifas',10,true);
create temporary table other38 as select * from public.save_knowledge_source('00000000-0000-4000-8000-000000000138','Privada',10,true);
create temporary table rule38 as select * from public.save_source_rule('00000000-0000-4000-8000-000000000038','Precios','REQUEST_INFORMATION',array['precio'],10,true,false,array[(select id from source38)],'{}','{}');
select ok(not (select allow_email_history from rule38),'Historial prohibido');
select is((select cardinality(terms) from rule38),1,'Conserva tema');
select is((select count(*) from public.source_rule_sources),1::bigint,'Relación explícita con propietario');
select throws_ok($q$select public.save_source_rule('00000000-0000-4000-8000-000000000038','Ajena','*','{}',10,true,false,array[(select id from other38)],'{}','{}')$q$,'P0001','SOURCE_NOT_FOUND','No vincula fuente ajena');
select throws_ok($q$select public.save_source_rule('00000000-0000-4000-8000-000000000038','Duplicada','*','{}',10,true,false,array[(select id from source38)],array[(select id from source38)],'{}')$q$,'P0001','INVALID_SOURCE_RULE','Roles excluyentes');
select throws_ok($q$select public.save_knowledge_source('00000000-0000-4000-8000-000000000138','Robo',10,true,(select id from source38))$q$,'P0001','SOURCE_NOT_FOUND','No modifica fuente ajena');
create temporary table doc38 as select * from public.reserve_source_document('00000000-0000-4000-8000-000000000038','tarifa.txt','text/plain',20,repeat('a',64));
select ok(public.assign_document_source(user_id,id,(select id from source38)),'Asigna fuente propia') from doc38;
select throws_ok($q$select public.assign_document_source('00000000-0000-4000-8000-000000000038',(select id from doc38),(select id from other38))$q$,'P0001','SOURCE_NOT_FOUND','No asigna documento a fuente ajena');
select ok(not public.assign_document_source('00000000-0000-4000-8000-000000000138',(select id from doc38),(select id from other38)),'No modifica documento ajeno');
select public.complete_indexed_source_document(user_id,id,'Consulta: 125 euros.',jsonb_build_object('indexer_version','mail037-v1','normalized_text','Consulta: 125 euros.','chunks',jsonb_build_array(jsonb_build_object('position',0,'section','Tarifas','content','Consulta: 125 euros.','start_offset',0,'end_offset',char_length('Consulta: 125 euros.'),'page_start',null,'page_end',null)))) from doc38;
create temporary table config38 as select public.get_knowledge_source_configuration('00000000-0000-4000-8000-000000000038') as value;
select is((select count(*) from public.search_knowledge_source_chunks('00000000-0000-4000-8000-000000000038','125',array[(select id from source38)],(select value->>'revision' from config38))),1::bigint,'Busca fuente autorizada');
select is((select count(*) from public.search_knowledge_source_chunks('00000000-0000-4000-8000-000000000138','125',array[(select id from source38)],public.get_knowledge_source_configuration('00000000-0000-4000-8000-000000000138')->>'revision')),0::bigint,'La búsqueda no cruza propietarios');
select ok(not has_function_privilege('authenticated','public.search_knowledge_source_chunks(uuid,text,uuid[],text,integer)','EXECUTE'),'No suplanta propietario con RPC');
select ok(not has_table_privilege('authenticated','public.source_rules','INSERT'),'Reglas solo desde backend');
select ok(not has_table_privilege('anon','public.knowledge_sources','SELECT'),'Anónimos sin acceso');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000138","role":"authenticated"}',true);
select is((select count(*) from public.knowledge_sources),1::bigint,'RLS solo fuentes propias');
select is((select count(*) from public.source_rules),0::bigint,'RLS oculta reglas ajenas');
select is((select count(*) from public.source_rule_sources),0::bigint,'RLS oculta enlaces ajenos');
reset role;
select public.save_knowledge_source('00000000-0000-4000-8000-000000000038','Tarifas',10,false,(select id from source38));
select throws_ok($q$select * from public.search_knowledge_source_chunks('00000000-0000-4000-8000-000000000038','125',array[(select id from source38)],(select value->>'revision' from config38))$q$,'P0001','SOURCE_CONFIGURATION_CHANGED','Configuración obsoleta no concede acceso');
select is((select count(*) from public.search_knowledge_source_chunks('00000000-0000-4000-8000-000000000038','125',array[(select id from source38)],public.get_knowledge_source_configuration('00000000-0000-4000-8000-000000000038')->>'revision')),0::bigint,'Fuente desactivada no devuelve hechos');
select throws_like($q$select public.delete_knowledge_source_item('00000000-0000-4000-8000-000000000038','source',(select id from source38))$q$,'%violates foreign key constraint%','No elimina fuentes en uso');
select ok(public.delete_knowledge_source_item('00000000-0000-4000-8000-000000000038','rule',(select id from rule38)),'Elimina regla');
select is((select count(*) from public.source_rule_sources),0::bigint,'Elimina sus enlaces');
select ok(public.assign_document_source(user_id,id,null),'Desasigna documento sin borrarlo') from doc38;
select ok(public.delete_knowledge_source_item('00000000-0000-4000-8000-000000000038','source',(select id from source38)),'Elimina fuente sin asociaciones');
select is((select count(*) from public.source_documents),1::bigint,'Conserva documento');
insert into public.knowledge_sources(user_id,title) select '00000000-0000-4000-8000-000000000038','Grupo '||n from generate_series(1,20) n;
select throws_ok($q$select public.save_knowledge_source('00000000-0000-4000-8000-000000000038','Límite',10,true)$q$,'P0001','SOURCE_LIMIT','Cuota de fuentes en la base');
insert into public.source_rules(user_id,title,intent_key,enabled) select '00000000-0000-4000-8000-000000000038','Regla '||n,'*',false from generate_series(1,50) n;
select throws_ok($q$select public.save_source_rule('00000000-0000-4000-8000-000000000038','Límite','*','{}',10,true,false,array[(select id from public.knowledge_sources where user_id='00000000-0000-4000-8000-000000000038' limit 1)],'{}','{}')$q$,'P0001','RULE_LIMIT','Cuota de reglas en la base');
select * from finish();
rollback;
